[IO.File]::WriteAllBytes(
  (Join-Path (Get-Location) $path),
  [Convert]::FromBase64String($b64)
)

Write-Host ''
Write-Host "  덮어씀  $path" -ForegroundColor Green

if (Select-String -Path $path -Pattern 'pinchRef' -Quiet) {
  Write-Host '  [OK] 핀치 확대' -ForegroundColor Green
} else {
  Write-Host '  [실패] 핀치 확대' -ForegroundColor Red
}

Write-Host ''
Write-Host '휴대폰에서 확인하려면:' -ForegroundColor Cyan
Write-Host '  npm run dev -- --host'
Write-Host '  터미널에 뜨는 Network 주소를 휴대폰 브라우저에 입력'
